#!/usr/bin/env node
/**
 * build-early-hints-headers.mjs (S175 #3 · early-hints-103)
 *
 * Generates the Cloudflare Pages `_headers` file with Link preload headers
 * for the current shell assets, sourced from assets/shell-manifest.json.
 * Cloudflare converts cached Link headers into 103 Early Hints (zone setting
 * enabled S175), so browsers start fetching shell CSS/JS before the HTML
 * response completes.
 *
 * Regenerated by `npm run build` after build-shell-assets — hashes never
 * drift because they come from the same manifest the pages reference.
 *
 * Usage:
 *   node scripts/build-early-hints-headers.mjs            # write _headers
 *   node scripts/build-early-hints-headers.mjs --check    # drift gate
 */
import fs from 'node:fs';
import path from 'node:path';
import url from 'node:url';

const __dirname = path.dirname(url.fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const OUT = path.join(ROOT, '_headers');
const CHECK = process.argv.includes('--check');

const manifest = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets', 'shell-manifest.json'), 'utf8'));

// S241 console-truth prune: preload ONLY render-critical assets. Deferred shell
// JS is intentionally not guaranteed to execute within Chrome's preload warning
// window, so Link-preloading it creates false "resource not used" console noise.
// Critical path = shell CSS. Interaction scripts stay normal deferred assets.
const PRELOADS = [
  { key: 'style', as: 'style' },
];

const lines = ['# generated-by: scripts/build-early-hints-headers.mjs — do not hand-edit', '/*'];
lines.push('  Link: </agents.json>; rel=alternate; type="application/json"; title="VaultSpark AI agent discovery manifest"');
for (const p of PRELOADS) {
  const asset = manifest.assets[p.key];
  if (!asset) continue;
  lines.push(`  Link: </${asset.path.replace(/\\/g, '/')}>; rel=preload; as=${p.as}`);
}
const content = lines.join('\n') + '\n';

if (CHECK) {
  const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (current !== content) {
    console.error('build-early-hints-headers --check: _headers drift; run node scripts/build-early-hints-headers.mjs');
    process.exit(1);
  }
  console.log('build-early-hints-headers --check: ok');
  process.exit(0);
}

fs.writeFileSync(OUT, content);
console.log(`build-early-hints-headers → _headers (${PRELOADS.length} preload(s), shell ${manifest.version.slice(0, 10)}…)`);
